// Generated by tools/prepare-level2.py from the original C64 Stage 2.
// Pixel codes: 0 = brown ($9), 1 = pink ($a), 2 = red ($2), 3 = cell accent ($5/$7).
.const TERRAIN2_BACKGROUND = 9
.const TERRAIN2_SCREEN_COLORS = $a2
.const TERRAIN2_EMPTY_PIXEL_CODE = 0
.const TERRAIN2_MAP_WIDTH = 128
.const TERRAIN2_MAP_HEIGHT = 8
.const TERRAIN2_TILE_COUNT = 181
.var level2TilesFile = LoadBinary("assets/level2-tiles.bin")
.var level2MapFile = LoadBinary("assets/level2-tv-map.bin")

* = $1000 "Original Stage 2 tiles and map"
terrain2Tiles:
    .fill level2TilesFile.getSize(), level2TilesFile.get(i)
terrain2TilesEnd:
.assert "Stage 2 tiles have eight bytes", terrain2TilesEnd - terrain2Tiles, TERRAIN2_TILE_COUNT * 8
.align $100
terrain2MapStart:
terrain2MapRow0:
    .fill 128, level2MapFile.get(i + 0)
terrain2MapRow1:
    .fill 128, level2MapFile.get(i + 128)
terrain2MapRow2:
    .fill 128, level2MapFile.get(i + 256)
terrain2MapRow3:
    .fill 128, level2MapFile.get(i + 384)
terrain2MapRow4:
    .fill 128, level2MapFile.get(i + 512)
terrain2MapRow5:
    .fill 128, level2MapFile.get(i + 640)
terrain2MapRow6:
    .fill 128, level2MapFile.get(i + 768)
terrain2MapRow7:
    .fill 128, level2MapFile.get(i + 896)
terrain2MapEnd:
.assert "Stage 2 map has eight rows", terrain2MapEnd - terrain2MapStart, 1024
.assert "Stage 2 tiles and map fit below $2000", terrain2MapEnd <= $2000, true

* = $b200 "Original Stage 2 accent maps"
.var level2AccentFile3 = LoadBinary("assets/level2-accents.bin")
.align $100
terrain2AccentMap:
    .fill level2AccentFile3.getSize(), level2AccentFile3.get(i)
.assert "Stage 2 accent region 3 has four phases", * - terrain2AccentMap, 512
.assert "Stage 2 accent region 3 is page aligned", <terrain2AccentMap, 0

.var level2AccentFile0 = LoadBinary("assets/level2-perspective-accents.bin")
.align $100
terrain2PerspectiveAccentMap:
    .fill level2AccentFile0.getSize(), level2AccentFile0.get(i)
.assert "Stage 2 accent region 0 has four phases", * - terrain2PerspectiveAccentMap, 512
.assert "Stage 2 accent region 0 is page aligned", <terrain2PerspectiveAccentMap, 0

.var level2AccentFile1 = LoadBinary("assets/level2-perspective-middle-accents.bin")
.align $100
terrain2PerspectiveMiddleAccentMap:
    .fill level2AccentFile1.getSize(), level2AccentFile1.get(i)
.assert "Stage 2 accent region 1 has four phases", * - terrain2PerspectiveMiddleAccentMap, 512
.assert "Stage 2 accent region 1 is page aligned", <terrain2PerspectiveMiddleAccentMap, 0

.var level2AccentFile2 = LoadBinary("assets/level2-perspective-right-accents.bin")
.align $100
terrain2PerspectiveRightAccentMap:
    .fill level2AccentFile2.getSize(), level2AccentFile2.get(i)
.assert "Stage 2 accent region 2 has four phases", * - terrain2PerspectiveRightAccentMap, 512
.assert "Stage 2 accent region 2 is page aligned", <terrain2PerspectiveRightAccentMap, 0

terrain2DataEnd:
.assert "Stage 2 accent maps end at $ba00", terrain2DataEnd, $ba00
.var TERRAIN2_PERSPECTIVE_ACCENT_MAPS = List()
.eval TERRAIN2_PERSPECTIVE_ACCENT_MAPS.add(terrain2PerspectiveAccentMap)
.eval TERRAIN2_PERSPECTIVE_ACCENT_MAPS.add(terrain2PerspectiveMiddleAccentMap)
.eval TERRAIN2_PERSPECTIVE_ACCENT_MAPS.add(terrain2PerspectiveRightAccentMap)
.eval TERRAIN2_PERSPECTIVE_ACCENT_MAPS.add(terrain2AccentMap)
